+            string listSpecialType = "," + SubjectSpecialType.BinhThuong.ToString() + "," + SubjectSpecialType.GiaoDucQuocPhong.ToString() + "," + SubjectSpecialType.GiaoDucTheChat.ToString() + "," + SubjectSpecialType.ChinhTri.ToString() + ",";
